style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url(https://drive.google.com/file/d/1yDprl_N5fKf0QC3JmXKW6mf3uDGaQ0PZ/view); /* Replace with your background image URL */
        background-size: cover; /* Make the image cover the whole page */
        background-attachment: fixed; /* Keep the background fixed when scrolling */
        background-position: center; /* Center the background image */
    }

    /* Optional: Style other elements (e.g., headers or navigation bar) */
    #header, .navbar {
        background: rgba(0, 0, 0, 0.8); /* Add transparency for visibility */
    }

    /* Optional: Hide default Roblox background colors */
    .content {
        background-color: transparent !important;
    }
}
